pub async fn user_exists(pool: &PgPool, tracker: &Tracker, user_id: i64) -> Result<bool, sqlx::Error> {
    let row = tracker
        .run(sqlx::query("SELECT 1 FROM users WHERE id = $1").bind(user_id).fetch_optional(pool))
        .await?;
    Ok(row.is_some())
}

